/// <summary>
/// getAccuracyReport's answer. ErrorCode: NOT_SUPERVISOR, INVALID_REQUEST, GROUPING_NOT_AVAILABLE.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountAccuracyResponse
{
    boolean success;
    str     errorCode;
    str     currencyCode;
    int     countedLines;
    int     accurateLines;
    real    overallPct;
    List    rows;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('CurrencyCode')]
public str parmCurrencyCode(str _value = currencyCode)
{
    currencyCode = _value;
    return currencyCode;
}

[DataMemberAttribute('CountedLines')]
public int parmCountedLines(int _value = countedLines)
{
    countedLines = _value;
    return countedLines;
}

[DataMemberAttribute('AccurateLines')]
public int parmAccurateLines(int _value = accurateLines)
{
    accurateLines = _value;
    return accurateLines;
}

[DataMemberAttribute('OverallPct')]
public real parmOverallPct(real _value = overallPct)
{
    overallPct = _value;
    return overallPct;
}

[DataMemberAttribute('Rows'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsCountAccuracyRow))]
public List parmRows(List _value = rows)
{
    rows = _value;
    return rows;
}
